import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"38、【睽】 兑下离上","description":"周易集注 - 38、【睽】 兑下离上","frontmatter":{"title":"38、【睽】 兑下离上","description":"周易集注 - 38、【睽】 兑下离上"},"headers":[],"relativePath":"zh/classics/jizhu/042.md","filePath":"zh/classics/jizhu/042.md"}'),h={name:"zh/classics/jizhu/042.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_38、【睽】-兑下离上" tabindex="-1">38、【睽】 兑下离上 <a class="header-anchor" href="#_38、【睽】-兑下离上" aria-label="Permalink to “38、【睽】 兑下离上”">​</a></h1><p>睽字从目，目少睛也。目主见，故周公爻辞，初曰见恶人，三曰见舆曳，上曰见豕负涂，皆见字之意。若从耳，亦曰聧，盖耳聋之甚也。睽，乖异也。为卦上离下兑，火炎上，泽润下，二体相违，睽之义也。又中少二女同居，志不同，亦睽之义也。《序卦》：家道穷必乖，故受之以睽。家道穷者，教家之道理穷绝也，无教家之道理，则乖异矣，所以次家人。睽综家人，家人离之阴在二，巽之阴在四，皆得其正。睽则兑之阴居三，离之阴居五，皆居阳位，不得其正。不正，则家道穷，故曰家道穷必乖，故受之以睽。</p><p>《彖》曰：睽，火动而上，泽动而下，二女同居，其志不同行。说而丽乎明，柔进而上行，得中而应乎刚，是以小事吉。天地睽，而其事同也;男女睽，而其志通也;万物睽，而其事类也。睽之时用大矣哉!</p><p>以卦象卦德卦综卦体，释卦名卦辞，极言其理而赞之。火燥炎上，泽湿就下，物性本然之睽。中女配坎，少女配艮，人情必然之睽，故名睽。兑说，离明，说丽乎明也。柔进而上行者，睽综家人，二卦同体，文王综为一卦，故《杂卦》曰：“睽外也，家人内也。”言家人下卦之离，进而为睽之上卦。六得乎五之中，而下应乎九二之刚也，三者皆柔之所为。柔本不能济事，又当睽乖之时，何由得小事吉?然说丽明则有德，进乎五则有位，应乎刚则有辅，因有此三者，是以小事吉也。事同者，知始作成化育之事同也。志通者，夫唱妇随，交感之情通也。事类者，声应气求，感应之机类也。天地不睽，不能成造化。男女不睽，不能成人道。万物不睽，不能成物类。此其时用所以大也，与坎蹇同。</p><h3 id="《象》曰-上火下泽-睽-君子以同而异。" tabindex="-1">《象》曰：上火下泽，睽，君子以同而异。 <a class="header-anchor" href="#《象》曰-上火下泽-睽-君子以同而异。" aria-label="Permalink to “《象》曰：上火下泽，睽，君子以同而异。”">​</a></h3><p>同者理，异者事，天下无不同之理，而有不同之事。异其事而同其理，所以同而异。如禹稷颜回同道，而出处异。微子比干箕子同仁，而去就死生异是也。《彖》辞言异而同，《象》辞言同而异，此所以为圣人之言也。</p><p>初九，悔亡，丧马勿逐自复，见恶人无咎。丧息浪反</p><p>丧者丧去也。中爻坎，为亟心之马，马亟心，倏然丧去，丧马之象也。勿逐自复者，不追逐而自还也。兑为悦体，凡易中言兑者，皆勿逐自复：如震之六二变兑，亦勿逐，七日得。既济六二变兑，亦勿逐，七日得是也。坎为盗，恶人之象也。中爻应爻离，持戈兵，亦恶人之象也。故大有初爻曰无交害，三爻曰小人害也。曰小人，则指离矣。见恶人者，恶人来而我即见之，不以恶人而拒绝也。离为目，见之象也。</p><p>初九当睽乖之时，上无应与相援，若有悔矣。然阳刚得正，故占者悔亡。但时正当睽，不可强求人之必合，故必去者不追，惟听其自还;来者不拒，虽恶人亦见之。此善于处睽者也。能如是，则悔亡而无咎矣，故又教占者，占中之象如此。</p><h3 id="《象》曰-见恶人-以辟咎也。辟音避" tabindex="-1">《象》曰：见恶人，以辟咎也。辟音避 <a class="header-anchor" href="#《象》曰-见恶人-以辟咎也。辟音避" aria-label="Permalink to “《象》曰：见恶人，以辟咎也。辟音避”">​</a></h3><p>当睽之时，行动即有咎病，故恶人亦不拒绝，而见之者，所以避咎也，咎即睽乖之咎。</p><p>九二，遇主于巷，无咎。</p><p>遇者相逢也，详见噬嗑六三遇毒。巷有二，街巷也，里巷也。兑错艮，艮为径路，里巷之象也。应爻离中虚，街巷之象也。离为日，主之象也。当睽之时，君臣相求，必欲拘堂陛之常分，则贤者无自而进矣。遇主于巷者，言不在廊庙之上，而在于巷道之中，如邓禹诸臣之遇光武是也。</p><p>九二以刚中而居悦体，上应六五，六五正当人心睽乖之时，柔弱已甚，欲思贤明之人以辅之。二以悦体，两情相合，正所谓得中而应乎刚也，故有遇主于巷之象。占者得此，睽而得合矣，故无咎。</p><h3 id="《象》曰-遇主于巷-未失道也。" tabindex="-1">《象》曰：遇主于巷，未失道也。 <a class="header-anchor" href="#《象》曰-遇主于巷-未失道也。" aria-label="Permalink to “《象》曰：遇主于巷，未失道也。”">​</a></h3><p>本卦离为戈兵，中爻离，亦为戈兵。兑为毁折，中爻又为坎陷。言君臣相遇于巷，岂不失道哉?然当天下睽乖之时，外而前有戈兵，后有戈兵，中原坎陷;内而主又柔弱，国势毁折，分崩离析，正危迫之秋，非但君择臣，臣亦择君时也。得一豪杰之士，即足以济睽矣，况又正应乎。圣人见得有此象，所以周公许其无咎，孔子许其未失道也，所以易经要玩象。</p><p>六三，见舆曳，其牛掣，其人天且劓，无初有终。掣音彻，劓鱼器反</p><p>上卦离为目，见之象也。见者六三与上九并见之也。又为牛，牛之象也。中爻坎，舆之象也，曳之象也。曳者拖也引也。掣者挽也，兑错艮为手，挽之象也。其人天者，指六三与上九也。六三阴也，居人位，故曰人。上九阳也，居天位，故曰天。周公爻辞之玄至此。错艮，又为鼻，鼻之象也。刑割鼻曰劓，鼻之上有戈兵，劓之象也。艮又为阍寺，刑人不曰阍寺，而曰劓者，戈兵之刑，在卦之上体也。若阍寺，则在下体矣，然非真割鼻也。鼻者通气出入之物，六三上九本乃正应，见其曳掣，怒气之发，如割鼻然，故取此象。且者未定之辞，言非真割鼻也。大意言车前必有牛，六三在车中，后二曳其车，前四掣其牛，所以上九见之而发怒也，此正所谓无初也。此皆本爻自有之象，易惟有此象，无此事，如入于左腹之类是也。后儒不悟象，所以将此等险辞，通鹘突放过去了。</p><p>六三不中不正，上应上九，欲与之合，然当睽乖之时，承乘皆不正之阳，亦欲与之相合，曳掣不能行，上下正应，见其曳掣，不胜其怒，故有此象。然阴阳正应，初虽睽乖，而终得合也，故其象占如此。</p><h3 id="《象》曰-见舆曳-位不当也。无初有终-遇刚也。" tabindex="-1">《象》曰：见舆曳，位不当也。无初有终，遇刚也。 <a class="header-anchor" href="#《象》曰-见舆曳-位不当也。无初有终-遇刚也。" aria-label="Permalink to “《象》曰：见舆曳，位不当也。无初有终，遇刚也。”">​</a></h3><p>阴居阳位，故不当。遇刚者，遇上九也。</p><p>九四，睽孤，遇元夫。交孚，厉无咎。</p><p>元者大也，夫者人也。阳为大人，阴为小人，指初为大人也。交孚者，同德相信也。厉者，竞竞然危心以处之，惟恐交孚之不至也。</p><p>九四以阳刚当睽之时，左右之邻皆阴柔之小人，孤立而无助者也，故有睽孤之象。然性本离明，知初九为大人君子，与之同德相信，故又有遇元夫交孚之象。然必危心以处之，方可无咎。故又教占者如此。</p><h3 id="《象》曰-交孚无咎-志行也。" tabindex="-1">《象》曰：交孚无咎，志行也。 <a class="header-anchor" href="#《象》曰-交孚无咎-志行也。" aria-label="Permalink to “《象》曰：交孚无咎，志行也。”">​</a></h3><p>志行者，二阳同德而相与济睽之志行也。盖睽者乖之极，孤者睽之极，二德交孚，则睽者可合，孤者有朋，志可行，而难可济，不特无咎而已也。</p><p>六五，悔亡，厥宗噬肤，往何咎?</p><p>宗字详见同人六二，噬肤详见噬嗑六二。言相合甚易，如噬肤之柔脆也。九二遇主于巷，曰主者，尊之也。六五厥宗噬肤，曰宗者，亲之也。臣尊其君，君亲其臣，岂不足以济天下之睽。</p><p>六五当睽之时，以柔居尊，宜有悔矣，然质本文明，柔进上行，有柔中之德。下应刚中之贤，而虚己下贤之心甚笃，故悔可亡，有厥宗噬肤之象。惟其合之甚易，所以悔亡也。占者以是而往，睽可济矣，故无咎也。</p><h3 id="《象》曰-厥宗噬肤-往有庆也。" tabindex="-1">《象》曰：厥宗噬肤，往有庆也。 <a class="header-anchor" href="#《象》曰-厥宗噬肤-往有庆也。" aria-label="Permalink to “《象》曰：厥宗噬肤，往有庆也。”">​</a></h3><p>往则可以济睽，故有庆。</p><p>上九，睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。说吐活反</p><p>九四之孤，以人而孤也，因左右皆阴爻也。上九之孤，自孤也，因猜疑而孤也。见者上九自见之而疑也，负者背也，涂者泥也。离错坎，坎为豕，又为水，豕负涂之象也。坎为隐伏，载鬼之象也。又为弓，又为狐疑，张弓说弓，心狐疑不定之象也。变震为归妹，男悦女，女悦男，婚媾之象也。寇指九二九四，又坎为雨，雨之象也。遇雨者，遇六三也，雨则三之象也。三居泽之上，乃雨也。</p><p>上九以阳刚处明，终睽极之地，猜疑难合，故为睽孤。与六三本为正应，始见六三舆曳牛掣，乃疑其为豕，又疑其非豕而为鬼，方欲张弓射之，又疑其非鬼，乃脱弓而近于前，乃六三也。使非二四之寇，上则早与六三成其婚媾矣。始虽睽孤，终而群疑亡，又复相合，故有此象。往遇雨，又婚媾之象也。占者凡事必如是则吉。</p><h3 id="《象》曰-遇雨之吉-群疑亡也。" tabindex="-1">《象》曰：遇雨之吉，群疑亡也。 <a class="header-anchor" href="#《象》曰-遇雨之吉-群疑亡也。" aria-label="Permalink to “《象》曰：遇雨之吉，群疑亡也。”">​</a></h3><p>惟群疑亡，所以遇雨吉。</p>',36)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
